INSERT INTO products (id, name, description, price, images_json, category, stock, data_ai_hint) VALUES
('prod_001', 'Chronograph Excellence', 'A masterpiece of precision and style, this chronograph watch is designed for the modern man. Featuring a stainless steel case, sapphire crystal glass, and a sophisticated dial with multiple subdials, it offers both functionality and elegance. Water-resistant up to 100 meters.', 450.00, '["https://images.unsplash.com/photo-1524805444758-089113d48a6d?q=80&w=600&auto=format&fit=crop","https://placehold.co/600x600.png","https://placehold.co/600x600.png"]', 'Watches', 15, 'luxury watch'),
('prod_002', 'Titanium Smartwatch', 'Experience the future on your wrist. This smartwatch boasts a lightweight titanium frame, a vibrant AMOLED display, and a suite of health and fitness tracking features. Syncs seamlessly with your smartphone for notifications, calls, and music control. Long-lasting battery life.', 799.99, '["https://images.unsplash.com/photo-1546868871-7041f2a55e12?q=80&w=600&auto=format&fit=crop","https://placehold.co/600x600.png"]', 'Watches', 25, 'smart watch'),
('prod_003', 'Ultra-Slim Laptop', 'Power and portability combined. Our ultra-slim laptop features the latest generation processor, a stunning 4K display, and a sleek aluminum body. With all-day battery life and a backlit keyboard, it’s perfect for professionals on the go. Comes with 16GB RAM and 1TB SSD storage.', 1399.00, '["https://images.unsplash.com/photo-1525547719571-a2d4ac8945e2?q=80&w=600&auto=format&fit=crop","https://placehold.co/600x600.png"]', 'Laptops', 10, 'modern laptop'),
('prod_004', 'Gaming Beast Laptop', 'Unleash your gaming potential with this powerhouse. Equipped with a high-refresh-rate display, a top-tier graphics card, and an advanced cooling system. The customizable RGB keyboard and immersive audio will elevate your gaming experience to new heights.', 2100.50, '["https://images.unsplash.com/photo-1593642702821-c8da6771f0c6?q=80&w=600&auto=format&fit=crop","https://placehold.co/600x600.png","https://placehold.co/600x600.png"]', 'Laptops', 5, 'gaming laptop'),
('prod_005', 'Galaxy Pro Smartphone', 'Capture life in stunning detail with the Galaxy Pro. Its professional-grade camera system, brilliant dynamic display, and powerful processor make it a leader in its class. Features an intelligent S-Pen for ultimate productivity and creativity. 5G ready.', 1199.99, '["https://images.unsplash.com/photo-1601784551446-20c9e07cdbf1?q=80&w=600&auto=format&fit=crop","https://placehold.co/600x600.png"]', 'Smartphones', 30, 'modern smartphone'),
('prod_006', 'Pixel Perfect Smartphone', 'The smart choice for a smartphone. Renowned for its exceptional camera powered by AI, clean software experience, and tight integration with Google services. Get the best of Android with timely updates and helpful features that anticipate your needs.', 899.00, '["https://images.unsplash.com/photo-1610945415295-d9bbf067e59c?q=80&w=600&auto=format&fit=crop","https://placehold.co/600x600.png"]', 'Smartphones', 22, 'sleek smartphone'),
('prod_007', 'Minimalist Digital Watch', 'Simplicity meets sophistication. This digital watch features a clean, easy-to-read display in a slim and lightweight case. Perfect for everyday wear, it offers essential features like an alarm, stopwatch, and backlight in an understated design.', 150.00, '["https://images.unsplash.com/photo-1523275335684-37898b6baf30?q=80&w=600&auto=format&fit=crop"]', 'Watches', 40, 'minimalist watch'),
('prod_008', 'Creator Pro Laptop', 'The ultimate tool for creators. This laptop is built to handle demanding creative workflows with its color-accurate display, powerful GPU, and extensive port selection. Whether you are into video editing, 3D rendering, or graphic design, this machine has you covered.', 2500.00, '["https://images.unsplash.com/photo-1589561253898-768105ca91a8?q=80&w=600&auto=format&fit=crop","https://placehold.co/600x600.png"]', 'Laptops', 8, 'powerful laptop');
